package com.cryptostrategy.platform.backtesting.internal;
import static org.junit.jupiter.api.Assertions.*;import com.cryptostrategy.platform.backtesting.api.error.BacktestException;import com.cryptostrategy.platform.backtesting.api.model.*;import com.cryptostrategy.platform.marketdata.api.model.DatasetIntegrityResult;import com.cryptostrategy.platform.strategy.api.Strategy;import com.cryptostrategy.platform.strategy.api.model.*;import java.util.Map;import java.util.concurrent.atomic.AtomicBoolean;import org.junit.jupiter.api.Test;
class RunBacktestServiceTest{@Test void verifiesLineageAndDatasetBeforeAtomicStore(){BacktestTestFixture f=new BacktestTestFixture();AtomicBoolean lineage=new AtomicBoolean();AtomicBoolean stored=new AtomicBoolean();var service=new RunBacktestService(id->DatasetIntegrityResult.validResult(),f.reader(),command->lineage.set(true),result->{stored.set(true);return result;});Strategy hold=c->new StrategyDecision(StrategySignal.HOLD,c.evaluationTime(),f.reference,"HOLD","test",Map.of());service.run(f.command(1),hold);assertTrue(lineage.get());assertTrue(stored.get());}@Test void checksumFailureProducesNoPartialStore(){BacktestTestFixture f=new BacktestTestFixture();AtomicBoolean stored=new AtomicBoolean();var service=new RunBacktestService(id->DatasetIntegrityResult.invalid("tampered"),f.reader(),command->{},result->{stored.set(true);return result;});Strategy hold=c->new StrategyDecision(StrategySignal.HOLD,c.evaluationTime(),f.reference,"HOLD","test",Map.of());assertThrows(BacktestException.class,()->service.run(f.command(1),hold));assertFalse(stored.get());}}
